cells={(0,c) for c in [1,2,4,5]} | {(1,c) for c in range(6)} | {(2,c) for c in [1,2,4]} | {(3,c) for c in [2,3,4]}
tiles=[]
for r in range(6):
 for c in range(6):
  sq={(r,c),(r,c+1),(r+1,c),(r+1,c+1)}
  if sq<=cells: tiles.append(('1',sq))
  box=[(r,c),(r,c+1),(r+1,c),(r+1,c+1)]
  for miss in range(4):
   l=set(box); l.remove(box[miss])
   if l<=cells:
    color={0:'?',1:'?',2:'?',3:'?'}
    # colors known: missing top-left=2, bottom-left=3, top-right=4; missing bottom-right unknown
    col={0:'2',1:'4',2:'3',3:'5'}[miss]
    tiles.append((col,l))
sols=[]
def rec(rem,chosen):
 if not rem:
  sols.append(chosen); return
 x=min(rem)
 for col,t in tiles:
  if x in t and t<=rem:
   rec(rem-t,chosen+[(col,t)])
rec(cells,[])
len(sols), [[(co, sorted(t)) for co,t in s] for s in sols[:10]]
